spec.test_code:
from functions_lab import format_record, make_accumulator, merge_defaults

def test_make_accumulator_isolated():
    acc_a = make_accumulator(10)
    acc_b = make_accumulator()
    assert acc_a() == 11
    assert acc_a(4) == 15
    assert acc_b(3) == 3
    assert acc_a(-5) == 10

def test_format_record():
    assert format_record('a', 'b', 'c') == 'a, b, c'
    assert format_record('py', 'nvim', sep=' | ', upper=True) == 'PY | NVIM'
    assert format_record() == ''

def test_merge_defaults_non_mutating():
    base = {'lr': 0.001, 'epochs': 3}
    merged = merge_defaults(base, epochs=10, batch_size=32)
    assert merged == {'lr': 0.001, 'epochs': 10, 'batch_size': 32}
    assert base == {'lr': 0.001, 'epochs': 3}

